1	// The other tools' side of the oracle: react-docgen-typescript (RDT) and react-docgen prop types reduced to the `Norm`
2	// shape src/oracle-compare.ts compares, so all three tools are held to the checker by the same rules. Pure: nothing
3	// here talks to the checker.
4	//
5	// Both tools state a type as source text (RDT prints it, react-docgen keeps what was written), so there is one mapper,
6	// `typeFromText`, which reads the text with TypeScript's parser. What a tool leaves as a name stays a name, and what it
7	// cannot state (a truncated `Foo<...>`, an indexed access, a conditional type) is `opaque`, which the comparison reads
8	// as less precise, never wrong.
9	import ts from 'typescript'
10	import { bareName, MAX_DEPTH, prim, type Norm } from './oracle-compare.ts'
11	
12	const OPAQUE: Norm = { k: 'opaque' }
13	
14	const KEYWORDS = new Map<ts.SyntaxKind, string>([
15	  [ts.SyntaxKind.StringKeyword, 'string'],
16	  [ts.SyntaxKind.NumberKeyword, 'number'],
17	  [ts.SyntaxKind.BooleanKeyword, 'boolean'],
18	  [ts.SyntaxKind.BigIntKeyword, 'bigint'],
19	  [ts.SyntaxKind.SymbolKeyword, 'symbol'],
20	  [ts.SyntaxKind.UndefinedKeyword, 'undefined'],
21	  [ts.SyntaxKind.AnyKeyword, 'any'],
22	  [ts.SyntaxKind.UnknownKeyword, 'unknown'],
23	  [ts.SyntaxKind.NeverKeyword, 'never'],
24	  [ts.SyntaxKind.VoidKeyword, 'void'],
25	  [ts.SyntaxKind.ObjectKeyword, 'object'],
26	])
27	const ARRAYS = new Set(['Array', 'ReadonlyArray'])
28	
29	/** The name a member is declared with, when it is written as a plain name or string. */
30	const memberName = (name: ts.PropertyName | undefined) =>
31	  name && (ts.isIdentifier(name) || ts.isStringLiteral(name) || ts.isNumericLiteral(name)) ? name.text : undefined
32	
33	function literal(node: ts.LiteralTypeNode['literal']): Norm {
34	  switch (node.kind) {
35	    case ts.SyntaxKind.NullKeyword: {
36	      return prim('null')
37	    }
38	    case ts.SyntaxKind.TrueKeyword:
39	    case ts.SyntaxKind.FalseKeyword: {
40	      return { k: 'lit', value: node.kind === ts.SyntaxKind.TrueKeyword ? 'true' : 'false' }
41	    }
42	    case ts.SyntaxKind.NumericLiteral: {
43	      // The checker's literal value is the number, so `1.0` is `1`.
44	      return { k: 'lit', value: String(Number(node.text)) }
45	    }
46	    case ts.SyntaxKind.PrefixUnaryExpression: {
47	      const { operand } = node as ts.PrefixUnaryExpression
48	      return ts.isNumericLiteral(operand) ? { k: 'lit', value: `-${Number(operand.text)}` } : OPAQUE
49	    }
50	    case ts.SyntaxKind.StringLiteral:
51	    case ts.SyntaxKind.NoSubstitutionTemplateLiteral: {
52	      return { k: 'lit', value: (node as ts.StringLiteral).text }
53	    }
54	    case ts.SyntaxKind.BigIntLiteral: {
55	      return { k: 'lit', value: (node as ts.BigIntLiteral).text.replace(/n$/, '') }
56	    }
57	    default: {
58	      return OPAQUE
59	    }
60	  }
61	}
62	
63	function convert(node: ts.TypeNode, depth: number): Norm {
64	  if (depth > MAX_DEPTH) return OPAQUE
65	  const inner = (n: ts.TypeNode) => convert(n, depth + 1)
66	  const keyword = KEYWORDS.get(node.kind)
67	  if (keyword) return prim(keyword)
68	  if (ts.isParenthesizedTypeNode(node)) return convert(node.type, depth)
69	  if (ts.isLiteralTypeNode(node)) return literal(node.literal)
70	  if (ts.isTemplateLiteralTypeNode(node)) return prim('string')
71	  if (ts.isUnionTypeNode(node)) return { k: 'union', members: node.types.map((n) => inner(n)) }
72	  if (ts.isIntersectionTypeNode(node)) {
73	    const parts = node.types.map((n) => inner(n))
74	    // `string & {}` is a string, as the checker's side reads it.
75	    const meaningful = parts.filter((m) => !(m.k === 'object' && m.fields.length === 0 && !m.index))
76	    return meaningful.length === 1 ? meaningful[0] : { k: 'intersection', members: parts }
77	  }
78	  if (ts.isArrayTypeNode(node)) return { k: 'array', element: inner(node.elementType) }
79	  if (ts.isTupleTypeNode(node)) {
80	    // A named, optional or rest element is the type it wraps.
81	    const element = (n: ts.TypeNode): Norm => {
82	      if (ts.isNamedTupleMember(n) || ts.isOptionalTypeNode(n) || ts.isRestTypeNode(n)) return inner(n.type)
83	      return inner(n)
84	    }
85	    return { k: 'tuple', elements: node.elements.map((n) => element(n)) }
86	  }
87	  if (ts.isFunctionTypeNode(node)) {
88	    const params = node.parameters.map((p) => ({
89	      optional: Boolean(p.questionToken ?? p.initializer),
90	      rest: Boolean(p.dotDotDotToken),
91	      type: p.type ? inner(p.type) : OPAQUE,
92	    }))
93	    return { k: 'function', params, returns: inner(node.type) }
94	  }
95	  if (ts.isTypeLiteralNode(node)) {
96	    const [only] = node.members
97	    if (node.members.length === 1 && ts.isCallSignatureDeclaration(only)) {
98	      const params = only.parameters.map((p) => ({
99	        optional: Boolean(p.questionToken ?? p.initializer),
100	        rest: Boolean(p.dotDotDotToken),
101	        type: p.type ? inner(p.type) : OPAQUE,
102	      }))
103	      return { k: 'function', params, returns: only.type ? inner(only.type) : OPAQUE }
104	    }
105	    const fields = node.members.flatMap((m) => {
106	      const name = ts.isPropertySignature(m) || ts.isMethodSignature(m) ? memberName(m.name) : undefined
107	      return name === undefined ? [] : [name]
108	    })
109	    return {
110	      k: 'object',
111	      fields: fields.toSorted(),
112	      index: node.members.some((m) => ts.isIndexSignatureDeclaration(m)),
113	    }
114	  }
115	  if (ts.isTypeOperatorNode(node)) {
116	    // `readonly string[]` is the array; `keyof X` and `unique symbol` are not something both sides state.
117	    return node.operator === ts.SyntaxKind.ReadonlyKeyword ? convert(node.type, depth) : OPAQUE
118	  }
119	  if (ts.isTypeReferenceNode(node)) {
120	    const name = bareName(node.typeName.getText())
121	    if (ARRAYS.has(name) && node.typeArguments?.length === 1)
122	      return { k: 'array', element: inner(node.typeArguments[0]) }
123	    return { k: 'name', name }
124	  }
125	  if (ts.isImportTypeNode(node) && node.qualifier) return { k: 'name', name: bareName(node.qualifier.getText()) }
126	  // Indexed access, conditional, mapped, `typeof X`, `infer`, `this`: a tool that left one of these as written has not
127	  // evaluated it.
128	  return OPAQUE
129	}
130	
131	/** One TypeScript type, as written or as a tool printed it, reduced to a `Norm`. Text that does not parse as a type (a
132	 * printer's `...` for a type it cut short) is `opaque`. */
133	export function typeFromText(text: string): Norm {
134	  if (text.trim() === '') return OPAQUE
135	  // Parents are set so a node can print its own name. `parseDiagnostics` is not in the public typings.
136	  const source = ts.createSourceFile('type.ts', `type T = ${text}`, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
137	  const diagnostics = (source as unknown as { parseDiagnostics: unknown[] }).parseDiagnostics
138	  const [statement] = source.statements
139	  if (diagnostics.length > 0 || source.statements.length !== 1 || !ts.isTypeAliasDeclaration(statement)) return OPAQUE
140	  return convert(statement.type, 0)
141	}
142	
143	/** What react-docgen-typescript reports for a prop's type (`prop.type`): the printed text as `name`, or `enum` with the
144	 * literal `value`s when `shouldExtractLiteralValuesFromEnum` is on and the type is a literal union. */
145	export interface RdtType {
146	  name: string
147	  raw?: string
148	  value?: { value: string }[]
149	}
150	
151	/** An RDT prop type. A literal union is the union of its values; the `raw` name (`SizeType`) is the alias RDT expanded. */
152	export function rdtNorm(type: RdtType | undefined): Norm {
153	  if (!type) return OPAQUE
154	  if (type.name === 'enum') {
155	    if (!type.value?.length) return OPAQUE
156	    const alias = type.raw && /^[A-Za-z_$][\w$]*$/.test(type.raw) ? type.raw : undefined
157	    return { k: 'union', members: type.value.map((v) => typeFromText(v.value)), alias }
158	  }
159	  return typeFromText(type.name)
160	}
161	
162	/** What react-docgen reports for a prop's type (`prop.tsType`), without `signature`. */
163	export interface RdgType {
164	  name: string
165	  raw?: string
166	  value?: string
167	  elements?: RdgType[]
168	}
169	
170	// A `name` that is a kind of type react-docgen reports with a source text, not a type of that name.
171	const KINDS = new Set(['union', 'intersection', 'signature', 'tuple', 'Array', 'literal'])
172	
173	/** A react-docgen prop type: the source text it kept where it kept one (`raw`), else what its `name` and `elements` say. */
174	export function rdgNorm(type: RdgType | undefined): Norm {
175	  if (!type) return OPAQUE
176	  if (type.name === 'literal') return type.value === undefined ? OPAQUE : typeFromText(type.value)
177	  if (type.raw) return typeFromText(type.raw)
178	  const members = (type.elements ?? []).map((e) => rdgNorm(e))
179	  if (type.name === 'union' && members.length > 0) return { k: 'union', members }
180	  if (type.name === 'intersection' && members.length > 0) return { k: 'intersection', members }
181	  if (type.name === 'Array' && members.length === 1) return { k: 'array', element: members[0] }
182	  if (type.name === 'tuple' && members.length > 0) return { k: 'tuple', elements: members }
183	  return KINDS.has(type.name) ? OPAQUE : typeFromText(type.name)
184	}
