// react-docgen-typescript on one corpus (scripts/weekly.py): every component's props with their declaring file, plus
// RDT's own wall time and peak RSS. RDT comes from apps/oracle, with the options its harness uses.
//
// Usage: node scripts/rdt.mjs <file-list> <tsconfig> <out.json>
import { readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

const require = createRequire(fileURLToPath(new URL('../apps/oracle/package.json', import.meta.url)))
const { withCustomConfig } = require('react-docgen-typescript')

const [listFile, tsconfig, out] = process.argv.slice(2)
if (!out) {
  console.error('usage: node scripts/rdt.mjs <file-list> <tsconfig> <out.json>')
  process.exit(2)
}
const files = readFileSync(listFile, 'utf8').split('\n').filter(Boolean)
const start = performance.now()
const parser = withCustomConfig(tsconfig, {
  shouldExtractLiteralValuesFromEnum: true,
  shouldRemoveUndefinedFromOptional: true,
  propFilter: { skipPropsWithoutDoc: false },
})
const docs = parser.parse(files)
const wallMs = performance.now() - start
// `type` stays RDT's type name, which is the string "enum" for a literal union. The oracle (apps/oracle/src/tool-norm.ts)
// needs the whole type object (`raw`, and the literal `value` list), kept for a component's own props: React's inherited
// ones, about nine in ten of the total, are not compared.
const REACT_DIR = 'node_modules/@types/react/'
const components = docs.map((d) => ({
  file: d.filePath,
  name: d.displayName,
  props: Object.fromEntries(
    Object.entries(d.props ?? {}).map(([k, p]) => {
      const parent = p.parent?.fileName ?? p.declarations?.[0]?.fileName ?? ''
      const own = !parent.includes(REACT_DIR)
      return [
        k,
        { required: Boolean(p.required), type: p.type?.name ?? '', parent, ...(own && { typeObject: p.type }) },
      ]
    }),
  ),
}))
// `maxRSS` is in kilobytes on every platform Node supports.
const peakRssMiB = process.resourceUsage().maxRSS / 1024
writeFileSync(out, JSON.stringify({ wallMs, peakRssMiB, components }))
console.error(`dumped ${components.length} components in ${(wallMs / 1000).toFixed(1)} s, ${peakRssMiB.toFixed(0)} MiB`)
// react-docgen (what Storybook ships) on one corpus (scripts/weekly.py): every component's props, in the shape
// scripts/rdt.mjs writes, plus its own wall time and peak RSS. It parses each file with its default resolver and
// importer, as Storybook does: the importer follows imports to the file that declares a type, but nothing is inferred.
// Each prop keeps its `tsType` (without the signature tree) for apps/oracle/src/tool-norm.ts; a file react-docgen throws
// on is counted in `failed` and named in `failedFiles`.
//
// Usage: node scripts/rdg.mjs <file-list> <out.json>
import { readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { pathToFileURL, fileURLToPath } from 'node:url'

const require = createRequire(fileURLToPath(new URL('../apps/oracle/package.json', import.meta.url)))
const { parse } = await import(pathToFileURL(require.resolve('react-docgen')).href)

const [listFile, out] = process.argv.slice(2)
if (!out) {
  console.error('usage: node scripts/rdg.mjs <file-list> <out.json>')
  process.exit(2)
}
const files = readFileSync(listFile, 'utf8').split('\n').filter(Boolean)
const components = []
const failedFiles = []
const start = performance.now()
// The type without the parameter and member trees a signature carries: the oracle reads the `raw` source text.
const slim = (t) =>
  t && typeof t === 'object'
    ? Object.fromEntries(
        Object.entries(t)
          .filter(([key]) => key !== 'signature')
          .map(([key, v]) => [key, Array.isArray(v) ? v.map(slim) : v]),
      )
    : t
for (const file of files) {
  try {
    for (const doc of parse(readFileSync(file, 'utf8'), { filename: file })) {
      components.push({
        file,
        name: doc.displayName ?? '',
        props: Object.fromEntries(
          Object.entries(doc.props ?? {}).map(([k, p]) => [
            k,
            {
              required: Boolean(p.required),
              type: p.tsType?.raw ?? p.tsType?.name ?? '',
              parent: '',
              tsType: slim(p.tsType),
            },
          ]),
        ),
      })
    }
  } catch {
    failedFiles.push(file)
  }
}
const failed = failedFiles.length
const wallMs = performance.now() - start
// `maxRSS` is in kilobytes on every platform Node supports.
const peakRssMiB = process.resourceUsage().maxRSS / 1024
writeFileSync(out, JSON.stringify({ wallMs, peakRssMiB, failed, failedFiles, components }))
console.error(
  `${components.length} components from ${files.length} files (${failed} failed) in ${(wallMs / 1000).toFixed(1)} s`,
)
